test("Positive mock releases O3 only through evidence factory",stopifnot(cp$analytics$report_packets$O3$state=="ready",sum(vapply(cp$analytics$report_packets,function(p)p$state=="ready",logical(1)))==1))
test("PCoA remains audit-only even after passing checks",stopifnot(length(cp$analytics$inline_images)==1,cp$analytics$inline_images[[1]]$slot_id=="O3",!grepl("PCoA",cp$analytics$inline_images[[1]]$name)))
test("Ready O3 independently revalidates",d1_validate_packets(cp$analytics$report_packets,run,cp,cp$analytics$as_of_cutoff))
test("Changed published metrics are rejected",{bad<-cp$analytics$report_packets;bad$O3$payload$metrics$reference_variance_retained<-0.01;throws(d1_validate_packets(bad,run,cp,cp$analytics$as_of_cutoff))})
test("Challenger cannot replace primary in the ready slot",{bad<-cp$analytics$report_packets;bad$O3$payload$method_id<-"M06";throws(d1_validate_packets(bad,run,cp,cp$analytics$as_of_cutoff))})
test("Readiness config still cannot override publication checks",{bad<-cfg;bad$analytics$allow_ready_packets<-TRUE;throws(validate_analytics_config(bad))})
test("Sixth packet still rejected with valid O3 present",throws(d1_validate_packets(c(cp$analytics$report_packets,cp$analytics$report_packets[1]),run,cp,cp$analytics$as_of_cutoff)))
test("Ready map has exactly one allowlisted numerical image",{r<-d1_render_packets(cp,run,cfg);stopifnot(count_pattern('class="analytics-slot"',paste(r$html,collapse="\n"))==5,length(r$images)==1)})
run_audit_figures(root,run,runner=function(...)1L);build_email(root,run,cfg);qa<-validate_output(root,run,cfg)
test("Positive mock MIME includes seal plus PCA and no other chart",stopifnot(qa$passed,qa$inline_images==2,qa$country_sections==9))
test("Ready map caption retained in plaintext",stopifnot(grepl("reference variation",read_text(file.path(run,"daily_briefing.txt")),fixed=TRUE)))
features<-readRDS(file.path(run,"audit/analytics/artifacts/M02.rds"));snap<-readRDS(file.path(run,"audit/history/snapshot.rds"));again<-i2_feature_execute(cp,root,run,snap)
test("Second feature call reuses the exact frozen reference",stopifnot(again$reference_operation=="reused_frozen_reference",again$fitted_reference_id==features$fitted_reference_id))
test("Repeated transform matches the prior sparse feature matrix",stopifnot(identical(again$current,features$current)))
project<-i2_projection_execute(again,cp,root,run,"M05")
test("Projection transform reuses its trained reference model",stopifnot(project$reference_operation=="reused_reference_fit"))
test("Reused projection has unchanged coordinates",near(project$coordinates,readRDS(file.path(run,"audit/analytics/artifacts/M05.rds"))$coordinates))
test("Future report cutoff cannot admit later reference",{b<-cp;b$brief$date<-"2026-09-19";throws(i2_feature_execute(b,root,run,snap))})
# Execute the read-only CLI itself, not merely its internal functions.
model_files<-list.files(file.path(root,cfg$analytics$feature_reference_dir),recursive=TRUE,full.names=TRUE);model_before<-vapply(model_files,sha_file,character(1))
cli<-function(command)system2(file.path(R.home("bin"),"Rscript"),vapply(c("--vanilla",file.path(root,"reference_tool.R"),paste0("--command=",command),paste0("--store=",cfg$analytics$feature_reference_dir),if(isTRUE(getOption("unbrief.minimal")))"--minimal=true"),shQuote,character(1)),stdout=file.path(tmp,paste0("cli_",command,".log")),stderr=file.path(tmp,paste0("cli_",command,".log")))
test("Read-only reference list CLI executes successfully",stopifnot(cli("list")==0L))
test("Reference verification CLI executes source recomputation",stopifnot(cli("verify")==0L))
test("Both CLI commands leave every reference byte unchanged",stopifnot(identical(model_before,vapply(model_files,sha_file,character(1)))))
